import React, { useRef, useState } from 'react';
import emailjs from '@emailjs/browser';
import { motion } from 'framer-motion';
import { Mail, Linkedin, Github, Phone, Send, MapPin, CheckCircle } from 'lucide-react';

const Contact = () => {
  const form = useRef();
  const [isSent, setIsSent] = useState(false);

  const sendEmail = (e) => {
    e.preventDefault();

    // Replace these with your actual EmailJS IDs
    emailjs.sendForm('YOUR_SERVICE_ID', 'YOUR_TEMPLATE_ID', form.current, 'YOUR_PUBLIC_KEY')
      .then((result) => {
          setIsSent(true);
          form.current.reset();
          setTimeout(() => setIsSent(false), 5000); // Reset success message after 5s
      }, (error) => {
          console.log(error.text);
          alert("Something went wrong. Please try again.");
      });
  };

  return (
    <section id="contact" className="py-24 px-10 bg-[#f8f9fa]">
      <div className="container mx-auto max-w-6xl">
        <div className="text-center mb-16">
          <h2 className="text-4xl font-black tracking-tighter uppercase text-gray-900">Get In <span className="text-blue-600">Touch</span></h2>
          <p className="text-gray-500 mt-2 font-medium">Let's discuss your next project or internship opportunity</p>
        </div>

        <div className="grid md:grid-cols-2 gap-12 items-center">
          {/* Left Side: Info */}
          <div className="space-y-10">
            <div>
              <h3 className="text-3xl font-bold mb-4">Contact Me</h3>
              <p className="text-gray-600 leading-relaxed mb-8">
                Whether you have a question about my projects or a job opportunity, my inbox is always open.
              </p>

              <div className="space-y-6">
                <div className="flex items-center gap-5">
                  <div className="p-4 bg-blue-600 text-white rounded-xl shadow-lg"><Phone size={24} /></div>
                  <div>
                    <p className="text-xs font-bold text-gray-400 uppercase tracking-widest">Contact</p>
                    <p className="font-bold text-gray-800">+91-7878509131 </p>
                  </div>
                </div>
                <div className="flex items-center gap-5">
                  <div className="p-4 bg-blue-600 text-white rounded-xl shadow-lg"><Mail size={24} /></div>
                  <div>
                    <p className="text-xs font-bold text-gray-400 uppercase tracking-widest">Email</p>
                    <p className="font-bold text-gray-800">agrawalnaitik508@gmail.com </p>
                  </div>
                </div>
              </div>
            </div>
          </div>

          {/* Right Side: Form */}
          <motion.div className="bg-white p-8 md:p-12 rounded-[2.5rem] shadow-2xl shadow-blue-100/50 border border-gray-50">
            {isSent ? (
              <div className="text-center py-10">
                <CheckCircle size={60} className="text-green-500 mx-auto mb-4" />
                <h3 className="text-2xl font-bold">Message Sent!</h3>
                <p className="text-gray-500">I will get back to you soon, Naitik[cite: 1].</p>
              </div>
            ) : (
              <form ref={form} onSubmit={sendEmail} className="space-y-6">
                <div className="grid grid-cols-2 gap-6">
                  <div className="space-y-2">
                    <label className="text-xs font-bold text-gray-400 uppercase ml-1">First Name</label>
                    <input name="first_name" required type="text" className="w-full p-4 bg-gray-50 rounded-2xl border-2 border-transparent focus:border-blue-600 focus:bg-white outline-none transition-all" />
                  </div>
                  <div className="space-y-2">
                    <label className="text-xs font-bold text-gray-400 uppercase ml-1">Last Name</label>
                    <input name="last_name" required type="text" className="w-full p-4 bg-gray-50 rounded-2xl border-2 border-transparent focus:border-blue-600 focus:bg-white outline-none transition-all" />
                  </div>
                </div>
                <div className="space-y-2">
                  <label className="text-xs font-bold text-gray-400 uppercase ml-1">Email Address</label>
                  <input name="email" required type="email" className="w-full p-4 bg-gray-50 rounded-2xl border-2 border-transparent focus:border-blue-600 focus:bg-white outline-none transition-all" />
                </div>
                <div className="space-y-2">
                  <label className="text-xs font-bold text-gray-400 uppercase ml-1">Your Message</label>
                  <textarea name="message" required rows="4" className="w-full p-4 bg-gray-50 rounded-2xl border-2 border-transparent focus:border-blue-600 focus:bg-white outline-none transition-all resize-none"></textarea>
                </div>
                <button type="submit" className="w-full bg-blue-600 text-white py-5 rounded-2xl font-black uppercase tracking-widest hover:bg-black transition-all flex items-center justify-center gap-3 shadow-lg shadow-blue-200">
                  Send Message <Send size={20} />
                </button>
              </form>
            )}
          </motion.div>
        </div>
      </div>
    </section>
  );
};

export default Contact;
